static const char LIB_AST[] = "#lang: es\n// ast_nodes.syn " "\xe2" "\x80" "\x94" " Tipos compuestos del AST en Synapse puro\n// Cada estructura define un nodo del arbol. Los campos que apuntan\n// a otras estructuras del AST se convierten automaticamente en\n// punteros en C para evitar recursion infinita en el tipo.\n\nestructura Token:\n    tipo: entero\n    lexema: texto\n    linea: entero\n    columna: entero\n\nestructura Nodo:\n    tipo: texto\n\nestructura ListaNodo:\n    cabeza: Nodo\n    cola: ListaNodo\n\nestructura Programa:\n    tipo: texto\n    sentencias: ListaNodo\n\nestructura Identificador:\n    tipo: texto\n    nombre: texto\n\nestructura LiteralNumero:\n    tipo: texto\n    valor: entero\n\nestructura LiteralCadena:\n    tipo: texto\n    valor: texto\n\nestructura OpBinaria:\n    tipo: texto\n    izquierdo: Nodo\n    operador: Token\n    derecho: Nodo\n\nestructura OpUnaria:\n    tipo: texto\n    operador: Token\n    expr: Nodo\n\nestructura LlamadaFuncion:\n    tipo: texto\n    nombre: texto\n    argumentos: ListaNodo\n\nestructura ExprAccesoCampo:\n    tipo: texto\n    objeto: Nodo\n    nombre_campo: texto\n\nestructura AsignacionVariable:\n    tipo: texto\n    nombre: texto\n    expresion: Nodo\n\nestructura AsignacionCampo:\n    tipo: texto\n    objeto: Nodo\n    nombre_campo: texto\n    expresion: Nodo\n\nestructura SentenciaSi:\n    tipo: texto\n    condicion: Nodo\n    cuerpo: ListaNodo\n    cuerpo_sino: ListaNodo\n\nestructura SentenciaMientras:\n    tipo: texto\n    condicion: Nodo\n    cuerpo: ListaNodo\n\nestructura SentenciaRetornar:\n    tipo: texto\n    expr: Nodo\n\nestructura SentenciaExpr:\n    tipo: texto\n    expr: Nodo\n\nestructura LogLlamada:\n    tipo: texto\n    argumentos: ListaNodo\n\nestructura Parametro:\n    tipo: texto\n    nombre: texto\n    tipo_param: texto\n    es_transferencia: booleano\n\nestructura ListaParametro:\n    cabeza: Parametro\n    cola: ListaParametro\n\nestructura DefinicionFuncion:\n    tipo: texto\n    nombre: texto\n    parametros: ListaParametro\n    tipo_retorno: texto\n    requiere: ListaNodo\n    garantiza: ListaNodo\n    cuerpo: ListaNodo\n\nestructura DefinicionEstructura:\n    tipo: texto\n    nombre: texto\n    campos: ListaParametro\n\nestructura SentenciaRomper:\n    tipo: texto\n\nestructura SentenciaSiguiente:\n    tipo: texto\n\nestructura SentenciaLanzar:\n    tipo: texto\n    llamada: Nodo\n\nestructura SentenciaRecuperar:\n    tipo: texto\n    accion_critica: Nodo\n    plan_b: Nodo\n\nestructura SentenciaEscuchar:\n    tipo: texto\n    canal: Nodo\n    respuesta: Nodo\n\nestructura ExprTensor:\n    tipo: texto\n    filas: Nodo\n    columnas: Nodo\n\nestructura ExprIndice:\n    tipo: texto\n    expr: Nodo\n    indice: Nodo\n\nestructura ArgumentoTransferido:\n    tipo: texto\n    expr: Nodo\n\nestructura SentenciaImportar:\n    tipo: texto\n    ruta: texto\n\nestructura BloqueInseguro:\n    tipo: texto\n    cuerpo: ListaNodo\n\nestructura ExprObtenerDireccion:\n    tipo: texto\n    expr: Nodo\n\nestructura ExprDereferencia:\n    tipo: texto\n    expr: Nodo\n\nestructura ImportarC:\n    tipo: texto\n    ruta: texto\n    es_sistema: booleano\n\nestructura DeclaracionExterna:\n    tipo: texto\n    nombre: texto\n    parametros: ListaParametro\n    tipo_retorno: texto\n\nestructura ExprCrearCanal:\n    tipo: texto\n    tipo_contenido: texto\n    capacidad: Nodo\n\nestructura SentenciaEnviarCanal:\n    tipo: texto\n    canal: Nodo\n    valor: Nodo\n\nestructura ExprRecibirCanal:\n    tipo: texto\n    canal: Nodo\n";

static const char LIB_LEXER[] = "#lang: es\n// lexer.syn " "\xe2" "\x80" "\x94" " Lexer nativo de Synapse (fase de dise" "\xc3" "\xb1" "o)\n// Este archivo define las estructuras y la interfaz base para el tokenizador.\n\nestructura Token:\n    tipo: entero\n    valor: texto\n    linea: entero\n    columna: entero\n\nestructura ListaToken:\n    cabeza: Token\n    cola: ListaToken\n\nfuncion siguiente_token() -> Token:\n    // Estado interno del lexer:\n    //   - fuente: texto completo de entrada\n    //   - i: " "\xc3" "\xad" "ndice del car" "\xc3" "\xa1" "cter actual\n    //   - linea: n" "\xc3" "\xba" "mero de l" "\xc3" "\xad" "nea\n    //   - columna: n" "\xc3" "\xba" "mero de columna\n    //   - nivel_indent: pila de niveles de indentaci" "\xc3" "\xb3" "n\n    // Reglas de escaneo:\n    //   1) Ignorar espacios y tabulaciones internas.\n    //   2) Omitir comentarios de l" "\xc3" "\xad" "nea con `//`.\n    //   3) Detectar literales de cadena entre comillas dobles y simples.\n    //   4) Detectar n" "\xc3" "\xba" "meros enteros y de punto flotante.\n    //   5) Detectar identificadores y palabras clave multiling" "\xc3" "\xbc" "es.\n    //      - TOKEN_COINCIDIR  (es: 'coincidir', en: 'match', etc.)\n    //   6) Detectar operadores de dos caracteres: `->`, `=>`, `==`, `!=`, `<=`, `>=`.\n    //      - TOKEN_FLECHA  => (operador de rama en bloque coincidir)\n    //      - Si el puntero lee '=' y el siguiente car" "\xc3" "\xa1" "cter es '>': emitir TOKEN_FLECHA.\n    //      - Si el puntero lee '=' y el siguiente car" "\xc3" "\xa1" "cter NO es '>': emitir TOKEN_ASIGNACION.\n    //   7) Detectar tokens de un car" "\xc3" "\xa1" "cter: `() , . : + - * / % & < > =`.\n    //   8) Generar NEWLINE, INDENT y DEDENT seg" "\xc3" "\xba" "n la indentaci" "\xc3" "\xb3" "n en bloques.\n    //   9) Al final de entrada generar `EOF`.\n\n    retornar Token()\n\nfuncion lexar(codigo_fuente: texto) -> ListaToken:\n    // Inicializa el estado de lexer:\n    //   fuente = codigo_fuente\n    //   i = 0\n    //   linea = 1\n    //   columna = 1\n    //   lista_tokens = ListaToken()\n    // Pasos principales:\n    //   1) Validar declaraci" "\xc3" "\xb3" "n `#lang:` en la primera l" "\xc3" "\xad" "nea.\n    //   2) Iterar los caracteres hasta fin de archivo.\n    //   3) En cada paso invocar `siguiente_token()`.\n    //   4) Gestionar niveles de indentaci" "\xc3" "\xb3" "n con una pila.\n    //   5) A" "\xc3" "\xb1" "adir `NEWLINE` al final de cada l" "\xc3" "\xad" "nea relevante.\n    //   6) Generar `EOF` al terminar.\n    retornar ListaToken()\n";

static const char LIB_PARSER[] = "#lang: es\n// parser.syn " "\xe2" "\x80" "\x94" " Analizador sint" "\xc3" "\xa1" "ctico nativo de Synapse\n// Define el parser recursivo descendente y los nodos b" "\xc3" "\xa1" "sicos para construir el AST.\n\nimportar compiler.ast_nodes\n\nestructura Parser:\n    tokens: ListaToken\n    posicion: entero\n    linea_actual: entero\n    columna_actual: entero\n\nfuncion crear_parser(tokens: ListaToken) -> Parser:\n    // Inicializa el estado del parser con la lista completa de tokens.\n    retornar Parser()\n\nfuncion mirar(parser: Parser) -> Token:\n    // Retorna el token actual sin consumirlo.\n    retornar Token()\n\nfuncion avanzar(parser: Parser) -> Token:\n    // Consume el token actual y avanza la posici" "\xc3" "\xb3" "n.\n    retornar Token()\n\nfuncion parsear_programa(parser: Parser) -> Programa:\n    // Punto de entrada: parsea todas las declaraciones y definiciones.\n    retornar Programa()\n\nfuncion parsear_funcion(parser: Parser) -> DefinicionFuncion:\n    // Parsear una definici" "\xc3" "\xb3" "n de funci" "\xc3" "\xb3" "n con firma y cuerpo indentado.\n    retornar DefinicionFuncion()\n\nfuncion parsear_bloque(parser: Parser) -> ListaNodo:\n    // Parsea un bloque a partir de ':' e INDENT/DEDENT.\n    retornar ListaNodo()\n\nfunci" "\xc3" "\xb3" "n parsear_sentencia(parser: Parser) -> Nodo:\n    // Detectar sentencias de canal y delegar al parser correspondiente.\n    token_actual = mirar(parser)\n    si token_actual.tipo == TokenID.ARROW_LEFT:\n        // canal <- valor\n        retornar parsear_enviar_canal(parser)\n    sino si token_actual.tipo == TokenID.ARROW_RIGHT:\n        // canal ->\n        retornar parsear_recibir_canal(parser)\n    sino:\n        // Otras sentencias (placeholder)\n        retornar Nodo()\n\nfuncion parsear_expresion(parser: Parser) -> Nodo:\n    // Stub para parseo de expresiones.\n    retornar Nodo()\n\nfuncion volcar_ast(nodo: Nodo, nivel: entero) -> nulo:\n    // Vuelca el AST por stdout con indentacion jerarquica.\n    // Implementacion nativa incrustada en la generacion C.\n    retornar\n\nfunci" "\xc3" "\xb3" "n parsear_crear_canal(parser: Parser) -> ExprCrearCanal:\n    // Sintaxis: crear_canal<T>(capacidad)\n    // Consume 'crear_canal' token, tipo gen" "\xc3" "\xa9" "rico y capacidad\n    retornar ExprCrearCanal()\n\nfunci" "\xc3" "\xb3" "n parsear_enviar_canal(parser: Parser) -> SentenciaEnviarCanal:\n    // Sintaxis: canal <- valor\n    // Consume canal, operador ARROW_LEFT, valor\n    retornar SentenciaEnviarCanal()\n\nfunci" "\xc3" "\xb3" "n parsear_recibir_canal(parser: Parser) -> ExprRecibirCanal:\n    // Sintaxis: canal ->\n    // Consume canal, operador ARROW_RIGHT\n    retornar ExprRecibirCanal()\n\nfunci" "\xc3" "\xb3" "n parsear_contrato_requiere(parser: Parser) -> ListaNodo:\n    // Bloque que comienza con palabra clave 'requiere' seguido de ':' e INDENT/DEDENT\n    retornar ListaNodo()\n\nfunci" "\xc3" "\xb3" "n parsear_contrato_garantiza(parser: Parser) -> ListaNodo:\n    // Bloque que comienza con palabra clave 'garantiza' seguido de ':' e INDENT/DEDENT\n    retornar ListaNodo()\n\n// Extiende parsear_funcion para reconocer contratos\nfunci" "\xc3" "\xb3" "n parsear_funcion(parser: Parser) -> DefinicionFuncion:\n    // Parsear una definici" "\xc3" "\xb3" "n de funci" "\xc3" "\xb3" "n con firma y cuerpo indentado.\n    // Primero parsear firma habitual (nombre, par" "\xc3" "\xa1" "metros, tipo retorno)\n    // Luego opcionalmente parsear bloques 'requiere' y 'garantiza'\n    // Finalmente parsear cuerpo del bloque.\n    retornar DefinicionFuncion()\n";

static const char LIB_GENERATOR[] = "#lang: es\n// generator.syn " "\xe2" "\x80" "\x94" " Generador de c" "\xc3" "\xb3" "digo C nativo para Synapse.\n// Define la interfaz y la estructura del ciclo de Self-Hosting.\n\nimportar compiler.ast_nodes\n\nestructura Generador:\n    buffer: texto\n    indentacion: entero\n\nfuncion crear_generador() -> Generador:\n    // Inicializa el buffer de salida y el nivel de indentaci" "\xc3" "\xb3" "n.\n    generador = Generador()\n    generador.buffer = \"\"\n    generador.indentacion = 0\n    retornar generador\n\nfuncion escribir_linea(generador: Generador, linea: texto) -> nulo:\n    // A" "\xc3" "\xb1" "ade una l" "\xc3" "\xad" "nea al buffer con la indentaci" "\xc3" "\xb3" "n actual.\n    retornar\n\nfuncion aumentar_indentacion(generador: Generador) -> nulo:\n    generador.indentacion = generador.indentacion + 1\n\nfuncion disminuir_indentacion(generador: Generador) -> nulo:\n    generador.indentacion = generador.indentacion - 1\n    si generador.indentacion < 0:\n        generador.indentacion = 0\n\nfuncion generar_codigo(nodo: Nodo, programa: Programa) -> texto:\n    // Recorre el AST y construye el c" "\xc3" "\xb3" "digo C en el buffer.\n    generador = crear_generador()\n    escribir_linea(generador, \"#include <stdio.h>\")\n    escribir_linea(generador, \"#include <stdlib.h>\")\n    escribir_linea(generador, \"#include <stdint.h>\")\n    escribir_linea(generador, \"#include <string.h>\")\n    escribir_linea(generador, \"\")\n    visitar_programa(generador, programa)\n    retornar generador.buffer\n\nfuncion visitar_programa(generador: Generador, programa: Programa) -> nulo:\n    // Recorre las sentencias del programa principal.\n    retornar\n\nfuncion visitar_definicion_funcion(generador: Generador, fn: DefinicionFuncion) -> nulo:\n    // Genera la firma de funci" "\xc3" "\xb3" "n y su bloque de cuerpo.\n    retornar\n\nfuncion visitar_sentencia(generador: Generador, sentencia: Nodo) -> nulo:\n    // Enruta a la funci" "\xc3" "\xb3" "n espec" "\xc3" "\xad" "fica seg" "\xc3" "\xba" "n el tipo de sentencia.\n    retornar\n\nfuncion visitar_expresion(generador: Generador, expresion: Nodo) -> texto:\n    // Convierte expresiones del AST a c" "\xc3" "\xb3" "digo C v" "\xc3" "\xa1" "lido.\n    retornar \"\"\n\nfuncion visitar_literal(generador: Generador, literal: Nodo) -> texto:\n    // Convierte literales de n" "\xc3" "\xba" "mero, cadena o booleano.\n    retornar \"\"\n\nfuncion visitar_bloque(generador: Generador, cuerpo: ListaNodo) -> nulo:\n    // Genera el contenido de un bloque indentado.\n    retornar\n\nfuncion traducir_tipo_c(tipo_synapse: texto) -> texto:\n    // Mapea tipos Synapse a tipos C nativos.\n    si tipo_synapse == \"entero\":\n        retornar \"int\"\n    si tipo_synapse == \"decimal\":\n        retornar \"float\"\n    si tipo_synapse == \"texto\":\n        retornar \"CadenaSegura\"\n    si tipo_synapse == \"tensor\":\n        retornar \"Tensor\"\n    retornar tipo_synapse\n\n";

static const char LIB_IO[] = "#lang: es\r\n// cumple Manual 2 " "\xc2" "\xa7" "12\r\n// cumple Manual 2 " "\xc2" "\xa7" "5.1\r\n# cumple Manual 2 12: biblioteca estandar con contratos en toda funcion publica\r\n// std.io " "\xe2" "\x80" "\x94" " Entrada/Salida est" "\xc3" "\xa1" "ndar (consola y archivos)\r\n// Integrante de la Biblioteca Estandar de Synapse.\r\n// Cumple Manual 2 " "\xc2" "\xa7" "12: contratos requiere/garantiza en todas las funciones p" "\xc3" "\xba" "blicas.\r\n// cumple Manual 2 " "\xc2" "\xa7" "12: cada funcion publica IO lleva requiere/garantiza observable.\r\n//\r\n// Uso desde Synapse:\r\n//   importar std.io\r\n//   escribir(\"hola\")\r\n//   escribir_linea(\"mundo\")\r\n//   entrada = leer_linea()\r\n\r\nimportar std.sistema\r\n\r\nfuncion abrir(ruta: texto, modo: texto) -> Canal:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        1 == 1\r\n// cumple Manual 2 " "\xc2" "\xa7" "5.1: cl" "\xc3" "\xa1" "usulas booleanas (requiere antes del cuerpo,\r\n// garantiza tras cada retornar " "\xe2" "\x80" "\x94" " M2 " "\xc2" "\xa7" "5.1); dominio del handle M2 " "\xc2" "\xa7" "12.\r\n    requiere:\r\n        longitud(ruta) > 0\r\n    requiere:\r\n        longitud(modo) > 0\r\n    garantiza:\r\n        _resultado_.es_valido == 0 o _resultado_.es_valido == 1\r\n    ruta_segura = _validar_ruta_segura(ruta)\r\n    si ruta_segura == \"\":\r\n        retornar 0\r\n    retornar _syn_abrir(ruta_segura, modo)\r\n\r\nfuncion leer(c: Canal) -> texto:\r\n    // M2 " "\xc2" "\xa7" "5.1: la cl" "\xc3" "\xa1" "usula original `c >= 0` comparaba un Canal (struct)\r\n    // con un n" "\xc3" "\xba" "mero " "\xe2" "\x80" "\x94" " expresi" "\xc3" "\xb3" "n no booleana; exige canal v" "\xc3" "\xa1" "lido (campo).\r\n    requiere:\r\n        c.es_valido == 1\r\n    garantiza:\r\n        longitud(_resultado_) >= 0\r\n    retornar _syn_leer(c)\r\n\r\nexterno funcion cerrar_archivo(c: Canal) -> nulo\r\n\r\nfuncion escribir(texto: texto) -> nulo:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    garantiza:\r\n        1 == 1\r\n    requiere:\r\n        longitud(texto) >= 0\r\n    _syn_escribir(texto)\r\n\r\nfuncion escribir_linea(texto: texto) -> nulo:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    garantiza:\r\n        1 == 1\r\n    requiere:\r\n        longitud(texto) >= 0\r\n    _syn_escribir_linea(texto)\r\n\r\nfuncion leer_linea() -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        longitud(_resultado_) >= 0\r\n    retornar _syn_leer_linea()\r\n\r\n// stdin_eof(): 1 = stdin agotado (EOF), 0 = hay (posiblemente m" "\xc3" "\xa1" "s) entrada.\r\n// Permite a los bucles de lectura distinguir EOF de l" "\xc3" "\xad" "nea vac" "\xc3" "\xad" "a (H-EOF-1):\r\n// leer_linea() retorna \"\" en ambos casos; consultar stdin_eof() tras una\r\n// lectura vac" "\xc3" "\xad" "a decide si el flujo termin" "\xc3" "\xb3" " o el usuario presion" "\xc3" "\xb3" " Enter.\r\n// cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato garantiza sobre el dominio del resultado\r\nfuncion stdin_eof() -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        _resultado_ == 0 o _resultado_ == 1\r\n    retornar _syn_stdin_eof()\r\n\r\n// ============================================================\r\n// " "\xc2" "\xa7" "1.7.1 " "\xe2" "\x80" "\x94" " Leer bytes (lectura binaria de stdin)\r\n// ============================================================\r\n\r\nfuncion leer_bytes(cantidad: entero) -> texto:\r\n    requiere:\r\n        cantidad >= 0\r\n    garantiza:\r\n        longitud(_resultado_) >= 0\r\n    retornar _syn_leer_bytes(cantidad)\r\n\r\nexterno funcion _syn_abrir(ruta: texto, modo: texto) -> Canal\r\nexterno funcion _syn_leer(c: Canal) -> texto\r\nexterno funcion _syn_escribir(texto: texto) -> nulo\r\nexterno funcion _syn_escribir_linea(texto: texto) -> nulo\r\nexterno funcion _syn_leer_linea() -> texto\r\nexterno funcion _syn_stdin_eof() -> entero\r\nexterno funcion _syn_leer_bytes(cantidad: entero) -> texto\r\n\r\n// ============================================================\r\n// " "\xc2" "\xa7" "1.7 " "\xe2" "\x80" "\x94" " I/O de bajo nivel para LSP (fgetc, fprintf, fflush)\r\n// ============================================================\r\n\r\n// Lee un byte de stdin (0-255), o -1 si EOF\r\nexterno funcion _syn_fgetc_stdin() -> entero\r\n\r\n// Escribe texto formateado a un canal (0=stdout, 1=stderr)\r\n// Retorna el n" "\xc3" "\xba" "mero de bytes escritos\r\nexterno funcion _syn_fprintf(canalm: entero, formato: texto) -> entero\r\n\r\n// Escribe texto formateado con 1 argumento entero\r\nexterno funcion _syn_fprintf_i(canalm: entero, formato: texto, valor: entero) -> entero\r\n\r\n// Escribe texto formateado con 2 argumentos (entero + texto)\r\nexterno funcion _syn_fprintf_it(canalm: entero, formato: texto, val1: entero, val2: texto) -> entero\r\n\r\n// Flush de un canal (0=stdout, 1=stderr)\r\nexterno funcion _syn_fflush(canalm: entero) -> nulo\r\n\r\n// Desactiva buffering en un canal\r\nexterno funcion _syn_setbuf_null(canalm: entero) -> nulo\r\n";

static const char LIB_MEM[] = "#lang: es\r\n// std.mem " "\xe2" "\x80" "\x94" " Gestion de memoria con semantica de transferencia\r\n// Integrante de la Biblioteca Estandar de Sinaplink OS.\r\n//\r\n// Uso desde Synapse:\r\n//   importar std.mem\r\n//   bloque = reserva(1024)\r\n//   libera(-> bloque)\r\n\r\nfuncion reserva(tamano: int) -> tensor:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        1 == 1\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: tama" "\xc3" "\xb1" "o positivo; bloque no vac" "\xc3" "\xad" "o garantizado\r\n    requiere:\r\n        tamano > 0\r\n    garantiza:\r\n        longitud(_resultado_) >= tamano\r\n    retornar 0\r\n\r\nfuncion libera(bloque: tensor) -> nulo:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        1 == 1\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: bloque no vac" "\xc3" "\xad" "o para liberar\r\n    requiere:\r\n        longitud(bloque) > 0\r\n    retornar\r\n";

static const char LIB_MATH[] = "#lang: es\n// std.math " "\xe2" "\x80" "\x94" " Operaciones tensoriales para IA nativa\n// Integrante de la Biblioteca Estandar de Synapse.\n// Cumple Manual 2 " "\xc2" "\xa7" "12: contratos requiere/garantiza en todas las funciones p" "\xc3" "\xba" "blicas.\n//\n// Uso desde Synapse:\n//   importar std.math\n//   a = crear_tensor(2, 2)\n//   b = crear_tensor(2, 2)\n//   c = suma_tensor(a, b)\n//   d = producto_punto(a, b)\n//   e = relu(c)\n\nfuncion crear_tensor(filas: entero, columnas: entero) -> tensor:\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: precondiciones de dominio (dimensiones positivas)\n    requiere:\n        filas > 0\n    requiere:\n        columnas > 0\n    garantiza:\n        longitud(_resultado_) == filas * columnas\n    retornar 0\n\nfuncion suma_tensor(a: tensor, b: tensor) -> tensor:\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: tensores con la misma forma no vac" "\xc3" "\xad" "a\n    requiere:\n        longitud(a) > 0\n    requiere:\n        longitud(b) > 0\n    requiere:\n        longitud(a) == longitud(b)\n    garantiza:\n        longitud(_resultado_) == longitud(a)\n    retornar 0\n\nfuncion producto_punto(a: tensor, b: tensor) -> tensor:\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: tensores compatibles (misma longitud de vector)\n    requiere:\n        longitud(a) > 0\n    requiere:\n        longitud(b) > 0\n    requiere:\n        longitud(a) == longitud(b)\n    garantiza:\n        longitud(_resultado_) >= 1\n    retornar 0\n\nfuncion relu(a: tensor) -> tensor:\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: tensor no vac" "\xc3" "\xad" "o; resultado con misma forma\n    requiere:\n        longitud(a) > 0\n    garantiza:\n        longitud(_resultado_) == longitud(a)\n    retornar 0\n";

static const char LIB_FS[] = "// std.fs " "\xe2" "\x80" "\x94" " Operaciones nativas del sistema de archivos via FFI\n// Integrante de la Biblioteca Estandar de Synapse.\n//\n// Uso desde Synapse:\n//   importar std.fs\n//   a = abrir_archivo(\"test.txt\", \"w\")\n//   escribir_archivo(a, \"hola mundo\")\n//   cerrar_archivo(a)\n//\n// Nota: Los handles de archivo se almacenan como enteros opacos.\n//       La implementacion subyacente usa FILE* de C.\n\nimportar_c \"<stdio.h>\"\n\n// Tipo envoltorio para FILE* de C (almacenado como entero opaco)\nestructura Archivo:\n    handle: entero\n\n// Declaraciones externas de C standard library\nexterno funcion fopen(ruta: char*, modo: char*) -> entero\nexterno funcion fclose(archivo: entero) -> entero\nexterno funcion fputs(str: char*, archivo: entero) -> entero\n\n// Wrappers nativos en Synapse\n\nfuncion abrir_archivo(ruta: texto, modo: texto) -> Archivo:\n    a = Archivo()\n    a.handle = fopen(ruta, modo)\n    retornar a\n\nfuncion cerrar_archivo(a: Archivo) -> entero:\n    retornar fclose(a.handle)\n\nfuncion escribir_archivo(a: Archivo, contenido: texto) -> entero:\n    retornar fputs(contenido, a.handle)\n";

static const char LIB_SYS[] = "// std.sys " "\xe2" "\x80" "\x94" " Operaciones del sistema operativo via FFI\n// Integrante de la Biblioteca Estandar de Synapse.\n//\n// Uso desde Synapse:\n//   importar std.sys\n//   salir(0)\n\nimportar_c \"<stdlib.h>\"\n\n// Declaracion externa de la funcion exit(3) de C standard library\nexterno funcion exit(codigo: entero) -> nulo\n\n// Envoltorio nativo: finaliza el programa con un codigo de salida\nfuncion salir(codigo: entero) -> nulo:\n    exit(codigo)\n";

static const char LIB_MODELO[] = "#lang: es\r\n// cumple Manual 2 " "\xc2" "\xa7" "5.1\r\n// cumple Manual 2 " "\xc2" "\xa7" "12\r\n// std.modelo " "\xe2" "\x80" "\x94" " Inferencia de modelos de lenguaje locales (transformers GGUF)\r\n// Integrante de la Biblioteca Estandar de Synapse.\r\n//\r\n// Arquitectura:\r\n//   - Carga segura de pesos GGUF via memory-mapped I/O\r\n//   - Gesti" "\xc3" "\xb3" "n determinista de memoria (sin GC)\r\n//   - Zero-telemetry: inferencia completamente local\r\n//   - BPE tokenizer integrado\r\n//   - KV cache optimizada para inferencia autoregresiva\r\n//\r\n// Uso desde Synapse:\r\n//   importar std.modelo\r\n//   ctx = cargar_modelo(\"modelo.gguf\")\r\n//   si ctx != nulo:\r\n//       logits = evaluar(ctx, token_id)\r\n//       token = argmax(logits)\r\n//       texto = decodificar_token(ctx, token)\r\n//       // O directamente:\r\n//       respuesta = generar_texto(ctx, \"Hola mundo\", 100, 0.7, 40, 0.9)\r\n//   cerrar_modelo(ctx)\r\n\r\n// ============================================================\r\n// Declaraciones externas (implementadas en synapse_rt.c)\r\n// ============================================================\r\n\r\n// --- Carga y ciclo de vida ---\r\nexterno funcion _syn_modelo_cargar(ruta: texto) -> puntero\r\nexterno funcion _syn_modelo_cerrar(ctx: puntero) -> nulo\r\n\r\n// --- Evaluaci" "\xc3" "\xb3" "n e inferencia token a token ---\r\nexterno funcion _syn_modelo_evaluar(ctx: puntero, token_id: entero) -> tensor\r\nexterno funcion _syn_modelo_generar(ctx: puntero, token_id: entero, temperatura: decimal, top_k: entero, top_p: decimal) -> entero\r\n\r\n// --- Contexto (n_past, max_seq_len) ---\r\nexterno funcion _syn_modelo_n_past(ctx: puntero) -> entero\r\nexterno funcion _syn_modelo_reiniciar(ctx: puntero) -> nulo\r\nexterno funcion _syn_modelo_obtener_n_ctx(ctx: puntero) -> entero\r\nexterno funcion _syn_modelo_establecer_n_ctx(ctx: puntero, max_tokens: entero) -> nulo\r\n\r\n// --- Tokenizaci" "\xc3" "\xb3" "n ---\r\nexterno funcion _syn_modelo_decodificar_token(ctx: puntero, token_id: entero) -> texto\r\nexterno funcion _syn_modelo_vocab_tamano(ctx: puntero) -> entero\r\nexterno funcion _syn_modelo_codificar_contar(ctx: puntero, texto: texto) -> entero\r\nexterno funcion _syn_modelo_codificar_obtener(ctx: puntero, indice: entero) -> entero\r\n\r\n// --- Generaci" "\xc3" "\xb3" "n de texto de alto nivel ---\r\n// Procesa un prompt completo y genera texto autoregresivamente\r\nexterno funcion _syn_modelo_generar_texto(ctx: puntero, prompt: texto, max_tokens: entero, temperatura: decimal, top_k: entero, top_p: decimal) -> texto\r\n\r\n// --- Metadatos del modelo ---\r\nexterno funcion _syn_modelo_obtener_metadato(ctx: puntero, clave: texto) -> texto\r\nexterno funcion _syn_modelo_obtener_arquitectura(ctx: puntero) -> texto\r\nexterno funcion _syn_modelo_obtener_n_layers(ctx: puntero) -> entero\r\nexterno funcion _syn_modelo_obtener_n_embd(ctx: puntero) -> entero\r\nexterno funcion _syn_modelo_obtener_n_heads(ctx: puntero) -> entero\r\n\r\n// ============================================================\r\n// Wrappers p" "\xc3" "\xba" "blicos (Synapse idiom" "\xc3" "\xa1" "tico)\r\n// ============================================================\r\n\r\n// --- Carga y ciclo de vida ---\r\n\r\nfuncion cargar_modelo(ruta: texto) -> puntero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: ruta no vac" "\xc3" "\xad" "a; resultado puede ser nulo si falla la carga\r\n    requiere:\r\n        longitud(ruta) > 0\r\n    retornar _syn_modelo_cargar(ruta)\r\n\r\nfuncion cerrar_modelo(ctx: puntero) -> nulo:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo para cerrar\r\n    requiere:\r\n        ctx != nulo\r\n    garantiza:\r\n        1 == 1\r\n    _syn_modelo_cerrar(ctx)\r\n    retornar\r\n\r\n// --- Evaluaci" "\xc3" "\xb3" "n e inferencia ---\r\n\r\nfuncion evaluar(ctx: puntero, token_id: entero) -> tensor:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, token v" "\xc3" "\xa1" "lido\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        token_id >= 0\r\n    retornar _syn_modelo_evaluar(ctx, token_id)\r\n\r\nfuncion generar_token(ctx: puntero, token_id: entero, temperatura: decimal, top_k: entero, top_p: decimal) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, par" "\xc3" "\xa1" "metros de muestreo v" "\xc3" "\xa1" "lidos\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        token_id >= 0\r\n    requiere:\r\n        top_k > 0\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_generar(ctx, token_id, temperatura, top_k, top_p)\r\n\r\n// --- Gesti" "\xc3" "\xb3" "n de contexto ---\r\n\r\nfuncion n_past(ctx: puntero) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo\r\n    requiere:\r\n        ctx != nulo\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_n_past(ctx)\r\n\r\nfuncion reiniciar(ctx: puntero) -> nulo:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo\r\n    requiere:\r\n        ctx != nulo\r\n    garantiza:\r\n        1 == 1\r\n    _syn_modelo_reiniciar(ctx)\r\n    retornar\r\n\r\nfuncion obtener_n_ctx(ctx: puntero) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo\r\n    requiere:\r\n        ctx != nulo\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_obtener_n_ctx(ctx)\r\n\r\nfuncion establecer_n_ctx(ctx: puntero, max_tokens: entero) -> nulo:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, l" "\xc3" "\xad" "mite positivo\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        max_tokens > 0\r\n    garantiza:\r\n        1 == 1\r\n    _syn_modelo_establecer_n_ctx(ctx, max_tokens)\r\n    retornar\r\n\r\n// --- Tokenizaci" "\xc3" "\xb3" "n ---\r\n\r\nfuncion decodificar_token(ctx: puntero, token_id: entero) -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, token v" "\xc3" "\xa1" "lido\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        token_id >= 0\r\n    retornar _syn_modelo_decodificar_token(ctx, token_id)\r\n\r\nfuncion vocab_tamano(ctx: puntero) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo\r\n    requiere:\r\n        ctx != nulo\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_vocab_tamano(ctx)\r\n\r\nfuncion codificar_contar(ctx: puntero, texto: texto) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, texto no vac" "\xc3" "\xad" "o\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        longitud(texto) > 0\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_codificar_contar(ctx, texto)\r\n\r\nfuncion codificar_obtener(ctx: puntero, indice: entero) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, " "\xc3" "\xad" "ndice no negativo\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        indice >= 0\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_codificar_obtener(ctx, indice)\r\n\r\n// --- Generaci" "\xc3" "\xb3" "n de texto de alto nivel ---\r\n\r\nfuncion generar_texto(ctx: puntero, prompt: texto, max_tokens: entero, temperatura: decimal, top_k: entero, top_p: decimal) -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, prompt no vac" "\xc3" "\xad" "o, max_tokens positivo\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        longitud(prompt) > 0\r\n    requiere:\r\n        max_tokens > 0\r\n    requiere:\r\n        top_k > 0\r\n    retornar _syn_modelo_generar_texto(ctx, prompt, max_tokens, temperatura, top_k, top_p)\r\n\r\n// --- Metadatos ---\r\n\r\nfuncion obtener_metadato(ctx: puntero, clave: texto) -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, clave no vac" "\xc3" "\xad" "a\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        longitud(clave) > 0\r\n    retornar _syn_modelo_obtener_metadato(ctx, clave)\r\n\r\nfuncion obtener_arquitectura(ctx: puntero) -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo\r\n    requiere:\r\n        ctx != nulo\r\n    retornar _syn_modelo_obtener_arquitectura(ctx)\r\n\r\nfuncion obtener_n_layers(ctx: puntero) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo\r\n    requiere:\r\n        ctx != nulo\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_obtener_n_layers(ctx)\r\n\r\nfuncion obtener_n_embd(ctx: puntero) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo\r\n    requiere:\r\n        ctx != nulo\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_obtener_n_embd(ctx)\r\n\r\nfuncion obtener_n_heads(ctx: puntero) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo\r\n    requiere:\r\n        ctx != nulo\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_modelo_obtener_n_heads(ctx)\r\n\r\n// ============================================================\r\n// Declaraciones externas de Fine-Tuning (implementadas en fine_tuning.c)\r\n// ============================================================\r\n\r\n// --- Ciclo de vida de sesi" "\xc3" "\xb3" "n de fine-tuning ---\r\nexterno funcion _syn_ft_iniciar(ctx: puntero, lr: decimal, rank: entero, alpha: decimal) -> puntero\r\nexterno funcion _syn_ft_cerrar(sesion: puntero) -> nulo\r\n\r\n// --- Gesti" "\xc3" "\xb3" "n de adaptadores LoRA ---\r\nexterno funcion _syn_ft_agregar_adaptador(sesion: puntero, capa_idx: entero, tipo_capa: entero, rank: entero, alpha: decimal, dim_in: entero, dim_out: entero) -> entero\r\n\r\n// --- Dataset ---\r\nexterno funcion _syn_ft_agregar_ejemplo(sesion: puntero, tokens_entrada: puntero, len_in: entero, tokens_salida: puntero, len_out: entero, peso: decimal) -> entero\r\n\r\n// --- Entrenamiento ---\r\nexterno funcion _syn_ft_paso_entrenamiento(sesion: puntero) -> decimal\r\nexterno funcion _syn_ft_entrenar(sesion: puntero) -> decimal\r\nexterno funcion _syn_ft_evaluar_perdida(sesion: puntero, len_salida: entero, target_id: entero) -> decimal\r\n\r\n// --- Persistencia ---\r\nexterno funcion _syn_ft_guardar_pesos(sesion: puntero, ruta: texto) -> entero\r\nexterno funcion _syn_ft_cargar_pesos(sesion: puntero, ruta: texto) -> entero\r\n\r\n// --- Control de adaptadores ---\r\nexterno funcion _syn_ft_aplicar_adaptadores(sesion: puntero) -> entero\r\nexterno funcion _syn_ft_remover_adaptadores(sesion: puntero) -> nulo\r\n\r\n// --- Estad" "\xc3" "\xad" "sticas ---\r\nexterno funcion _syn_ft_obtener_perdida(sesion: puntero) -> decimal\r\nexterno funcion _syn_ft_obtener_paso(sesion: puntero) -> entero\r\n\r\n// ============================================================\r\n// Declaraciones externas de Cuantizaci" "\xc3" "\xb3" "n (implementadas en quantization.c)\r\n// ============================================================\r\n\r\n// --- Ciclo de vida ---\r\nexterno funcion _syn_qt_iniciar(formato: entero, block_size: entero) -> puntero\r\nexterno funcion _syn_qt_cerrar(sesion: puntero) -> nulo\r\n\r\n// --- Gesti" "\xc3" "\xb3" "n de tensores ---\r\nexterno funcion _syn_qt_agregar_tensor(sesion: puntero, datos: puntero, filas: entero, columnas: entero, nombre: texto) -> entero\r\nexterno funcion _syn_qt_cuantizar_tensor(sesion: puntero, idx: entero) -> entero\r\nexterno funcion _syn_qt_cuantizar_todos(sesion: puntero) -> entero\r\n\r\n// --- Descuantizaci" "\xc3" "\xb3" "n ---\r\nexterno funcion _syn_qt_descuantizar_tensor(sesion: puntero, idx: entero) -> puntero\r\n\r\n// --- FP16 " "\xe2" "\x86" "\x94" " FP32 ---\r\nexterno funcion _syn_qt_fp16_a_fp32(src: puntero, dst: puntero, n: entero) -> nulo\r\nexterno funcion _syn_qt_fp32_a_fp16(src: puntero, dst: puntero, n: entero) -> nulo\r\n\r\n// --- Persistencia ---\r\nexterno funcion _syn_qt_guardar(sesion: puntero, ruta: texto) -> entero\r\nexterno funcion _syn_qt_cargar(sesion: puntero, ruta: texto) -> entero\r\n\r\n// --- Selecci" "\xc3" "\xb3" "n din" "\xc3" "\xa1" "mica ---\r\nexterno funcion _syn_qt_seleccionar_formato(ram_mb: entero) -> entero\r\nexterno funcion _syn_qt_estimar_tamano_modelo(params_m: entero, formato: entero) -> decimal\r\n\r\n// ============================================================\r\n// Funciones helper de alto nivel\r\n// ============================================================\r\n\r\n// argmax: retorna el " "\xc3" "\xad" "ndice del valor m" "\xc3" "\xa1" "ximo en un tensor de logits\r\n// Equivalente a: argmax(logits) -> token_id\r\nfuncion argmax(logits: tensor) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: tensor no vac" "\xc3" "\xad" "o\r\n    requiere:\r\n        longitud(logits) > 0\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    inseguro:\r\n        asm(\"float* _d = logits.datos;\")\r\n        asm(\"int _n = (int)(logits.columnas);\")\r\n        asm(\"if (!_d || _n <= 0) return -1;\")\r\n        asm(\"float _max = _d[0];\")\r\n        asm(\"int _idx = 0;\")\r\n        asm(\"for (int _i = 1; _i < _n; _i++) {\")\r\n        asm(\"    if (_d[_i] > _max) { _max = _d[_i]; _idx = _i; }\")\r\n        asm(\"}\")\r\n        asm(\"return _idx;\")\r\n\r\n// muestra_logits: imprime los primeros N logits para depuraci" "\xc3" "\xb3" "n\r\nfuncion muestra_logits(logits: tensor, n: entero) -> nulo:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: tensor no vac" "\xc3" "\xad" "o, n positivo\r\n    requiere:\r\n        longitud(logits) > 0\r\n    requiere:\r\n        n > 0\r\n    garantiza:\r\n        1 == 1\r\n    inseguro:\r\n        asm(\"float* _d = logits.datos;\")\r\n        asm(\"int _max = n < (int)logits.columnas ? n : (int)logits.columnas;\")\r\n        asm(\"fprintf(stderr, \\\"[Modelo] Logits (primeros %d): \\\", _max);\")\r\n        asm(\"for (int _i = 0; _i < _max; _i++) {\")\r\n        asm(\"    fprintf(stderr, \\\"%.4f \\\", _d[_i]);\")\r\n        asm(\"}\")\r\n        asm(\"fprintf(stderr, \\\"\\\\n\\\");\")\r\n        retornar\r\n\r\n// generar_texto_simple: genera texto con par" "\xc3" "\xa1" "metros por defecto\r\n// temperatura=0.7, top_k=40, top_p=0.9\r\nfuncion generar_texto_simple(ctx: puntero, prompt: texto, max_tokens: entero) -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contexto no nulo, prompt no vac" "\xc3" "\xad" "o, max_tokens positivo\r\n    requiere:\r\n        ctx != nulo\r\n    requiere:\r\n        longitud(prompt) > 0\r\n    requiere:\r\n        max_tokens > 0\r\n    retornar _syn_modelo_generar_texto(ctx, prompt, max_tokens, 0.7, 40, 0.9)\r\n\r\n// ============================================================\r\n// Declaraciones externas de Destilaci" "\xc3" "\xb3" "n (implementadas en distillation.c)\r\n// ============================================================\r\n\r\n// --- Ciclo de vida ---\r\nexterno funcion _syn_kd_iniciar(temperatura: decimal, alpha: decimal, vocab_size: entero) -> puntero\r\nexterno funcion _syn_kd_cerrar(sesion: puntero) -> nulo\r\n\r\n// --- Gesti" "\xc3" "\xb3" "n de dataset ---\r\nexterno funcion _syn_kd_agregar_par(sesion: puntero, logits_t: puntero, logits_s: puntero, target_id: entero, peso: decimal) -> entero\r\n\r\n// --- C" "\xc3" "\xb3" "mputo de p" "\xc3" "\xa9" "rdida ---\r\nexterno funcion _syn_kd_divergencia_kl(logits_p: puntero, logits_q: puntero, n: entero, temperatura: decimal) -> decimal\r\nexterno funcion _syn_kd_perdida_combinada(logits_t: puntero, logits_s: puntero, target_id: entero, vocab_size: entero, temperatura: decimal, alpha: decimal) -> decimal\r\n\r\n// --- Destilaci" "\xc3" "\xb3" "n ---\r\nexterno funcion _syn_kd_paso_destilacion(sesion: puntero) -> decimal\r\nexterno funcion _syn_kd_destilar(sesion: puntero) -> decimal\r\n\r\n// --- Persistencia ---\r\nexterno funcion _syn_kd_guardar(sesion: puntero, ruta: texto) -> entero\r\nexterno funcion _syn_kd_cargar(sesion: puntero, ruta: texto) -> entero\r\n\r\n// --- Integraci" "\xc3" "\xb3" "n ---\r\nexterno funcion _syn_kd_estimar_reduccion(teacher_m: entero, student_m: entero, fmt: entero) -> decimal\r\n";

static const char LIB_ORACULO[] = "#lang: es\r\n// std.oraculo " "\xe2" "\x80" "\x94" " Bucle del Or" "\xc3" "\xa1" "culo (Generaci" "\xc3" "\xb3" "n + Compilaci" "\xc3" "\xb3" "n + Feedback Loop)\r\n// Integrante de la Biblioteca Estandar de Synapse.\r\n//\r\n// Uso desde Synapse:\r\n//   importar std.oraculo\r\n//   codigo = generar_codigo(modelo, \"Escribe un hola mundo\")\r\n//   si codigo != \"\":\r\n//       // usar codigo generado\r\n\r\nimportar std.modelo\r\n\r\n// --- Constantes del Or" "\xc3" "\xa1" "culo ---\r\n\r\nconstante MAX_TOKENS_GENERAR = 256\r\n\r\nconstante SYSTEM_PROMPT = \"Eres un asistente que escribe codigo en Synapse.#10El lenguaje Synapse usa las siguientes reglas:#10- Indentacion: multiplos de 4 espacios (no tabs)#10- No uses llaves {} para bloques de control#10- Usa #lang: es al inicio del codigo#10- Los bloques se definen por indentacion#10- Usa 'funcion nombre(param: tipo) -> tipo:' para definir funciones#10- Usa 'si condicion:' para condicionales#10- Usa 'mientras condicion:' para bucles#10- Usa 'retornar expr' para valores de retorno#10- Variables: 'nombre = expr'#10- Tipos: entero, decimal, texto, booleano, puntero, tensor, nulo#10- Los strings se escriben entre comillas dobles#10- No uses punto y coma al final de lineas#10- 'verdadero' y 'falso' para booleanos#10- 'nulo' para puntero nulo\"\r\n\r\n// --- Funciones externas de compilaci" "\xc3" "\xb3" "n ---\r\n\r\nexterno funcion _syn_compilar_codigo(fuente: texto) -> entero\r\nexterno funcion _syn_obtener_codigo_generado() -> texto\r\nexterno funcion _syn_obtener_error_compilacion() -> texto\r\nexterno funcion _syn_obtener_linea_error() -> entero\r\nexterno funcion _syn_extraer_bloque_codigo(texto: texto) -> texto\r\n// --- Wrappers p" "\xc3" "\xba" "blicos ---\r\n\r\nfuncion compilar_codigo(fuente: texto) -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        _resultado_ >= -1\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: c" "\xc3" "\xb3" "digo fuente no vac" "\xc3" "\xad" "o; resultado 0=" "\xc3" "\xa9" "xito, otro=error\r\n    requiere:\r\n        longitud(fuente) > 0\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_compilar_codigo(fuente)\r\n\r\nfuncion obtener_codigo_generado() -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        1 == 1\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: retorna el c" "\xc3" "\xb3" "digo generado por la " "\xc3" "\xba" "ltima llamada al modelo\r\n    garantiza:\r\n        longitud(_resultado_) >= 0\r\n    retornar _syn_obtener_codigo_generado()\r\n\r\nfuncion obtener_error_compilacion() -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        1 == 1\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: retorna el mensaje de error de la " "\xc3" "\xba" "ltima compilaci" "\xc3" "\xb3" "n fallida\r\n    garantiza:\r\n        longitud(_resultado_) >= 0\r\n    retornar _syn_obtener_error_compilacion()\r\n\r\nfuncion obtener_linea_error() -> entero:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        _resultado_ >= -1\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: n" "\xc3" "\xba" "mero de l" "\xc3" "\xad" "nea >= 0 (0 si sin error o sin info de l" "\xc3" "\xad" "nea)\r\n    garantiza:\r\n        _resultado_ >= 0\r\n    retornar _syn_obtener_linea_error()\r\n\r\nfuncion extraer_bloque_codigo(texto: texto) -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        1 == 1\r\n    garantiza:\r\n        1 == 1\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: extrae bloque de c" "\xc3" "\xb3" "digo fenced; resultado >= 0 chars\r\n    requiere:\r\n        longitud(texto) >= 0\r\n    garantiza:\r\n        longitud(_resultado_) >= 0\r\n    retornar _syn_extraer_bloque_codigo(texto)\r\n\r\n// generar_texto se importa de std.modelo (importar std.modelo arriba)\r\n\r\n// --- Bucle del Or" "\xc3" "\xa1" "culo ---\r\n\r\n// Genera c" "\xc3" "\xb3" "digo Synapse a partir de una instrucci" "\xc3" "\xb3" "n usando el modelo,\r\n// lo compila, y si hay errores, retroalimenta al modelo para corregirlos.\r\n// Retorna el c" "\xc3" "\xb3" "digo fuente Synapse generado (cadena vac" "\xc3" "\xad" "a si falla tras MAX_INTENTOS).\r\nfuncion generar_codigo(modelo: puntero, instruccion: texto, max_intentos: entero) -> texto:\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: contrato de dominio\r\n    requiere:\r\n        max_intentos >= 0\r\n    garantiza:\r\n        1 == 1\r\n    // cumple Manual 2 " "\xc2" "\xa7" "5.1: instrucci" "\xc3" "\xb3" "n no vac" "\xc3" "\xad" "a; reintentos positivos; resultado vac" "\xc3" "\xad" "o = fallo total\r\n    requiere:\r\n        longitud(instruccion) > 0\r\n    requiere:\r\n        max_intentos >= 1\r\n    garantiza:\r\n        longitud(_resultado_) >= 0\r\n    prompt_completo = SYSTEM_PROMPT\r\n    prompt_completo = concat(prompt_completo, \"#10#10Instruccion del usuario: \")\r\n    prompt_completo = concat(prompt_completo, instruccion)\r\n    prompt_completo = concat(prompt_completo, \"#10#10Genera SOLO el codigo Synapse (sin explicaciones):\")\r\n\r\n    intento = 0\r\n    ultimo_error = \"\"\r\n\r\n    mientras intento < max_intentos:\r\n        escribir_linea(concat(\"[Oraculo] Generando codigo... (Intento \", entero_a_texto(intento + 1)))\r\n        escribir_linea(concat(concat(concat(\"/\", entero_a_texto(max_intentos)), \")\"), \"\"))\r\n\r\n        si intento > 0:\r\n            prompt_completo = concat(prompt_completo, \"#10#10El compilador rechazo el codigo con el siguiente error: \")\r\n            prompt_completo = concat(prompt_completo, ultimo_error)\r\n            prompt_completo = concat(prompt_completo, \"#10#10Reescribe la funcion corrigiendo la infraccion. Genera SOLO el codigo corregido:\")\r\n\r\n        // Generar texto con el modelo\r\n        respuesta = generar_texto(modelo, prompt_completo, MAX_TOKENS_GENERAR, 0.7, 40, 0.9)\r\n\r\n        // Extraer bloque de c" "\xc3" "\xb3" "digo\r\n        codigo_generado = extraer_bloque_codigo(respuesta)\r\n        si codigo_generado == \"\":\r\n            codigo_generado = respuesta  // usar respuesta completa si no hay bloque\r\n\r\n        // Compilar el c" "\xc3" "\xb3" "digo\r\n        res = compilar_codigo(codigo_generado)\r\n\r\n        si res == 0:\r\n            escribir_linea(\"[Compilador] Exito. Binario generado.\")\r\n            retornar codigo_generado  // " "\xc3" "\xa9" "xito\r\n\r\n        // Capturar error para retroalimentaci" "\xc3" "\xb3" "n\r\n        error_msg = obtener_error_compilacion()\r\n        linea_err = obtener_linea_error()\r\n        escribir_linea(\"[Compilador] Error detectado: Re-inyectando contexto...\")\r\n        ultimo_error = concat(\"Linea \", entero_a_texto(linea_err))\r\n        ultimo_error = concat(ultimo_error, \": \")\r\n        ultimo_error = concat(ultimo_error, error_msg)\r\n\r\n        intento = intento + 1\r\n\r\n    escribir_linea(\"[Oraculo] Limite de intentos alcanzado.\")\r\n    retornar \"\"  // fallo tras max_intentos\r\n";
